import {AssetLoader,SceneManager,CharacterRegistry} from './foundation.js';
import {objects,materials,roster} from './data.js';
import {pathfind,blocked,cellAt} from './navigation.js';
const assets=await new AssetLoader().load({pip:'assets/pip.svg'}),scenes=new SceneManager(),characters=new CharacterRegistry(roster);
characters.register('Alex Thompson',{suit:'#cf4348'});
const $=s=>document.querySelector(s),canvas=$('canvas'),ctx=canvas.getContext('2d'),panel=$('#panel'),content=$('#content');
let saved={};try{saved=JSON.parse(localStorage.getItem('jacc-v1')||'{}')}catch{}
const state={x:130,y:460,path:[],pending:null,started:false,paused:false,action:null,timer:0,dug:0,last:null,ring:null,discoveries:new Set(saved.discoveries||[]),settings:{volume:.3,narration:false,reduced:matchMedia('(prefers-reduced-motion: reduce)').matches,effects:true,...saved.settings}};
function persist(){try{localStorage.setItem('jacc-v1',JSON.stringify({settings:state.settings,discoveries:[...state.discoveries]}))}catch{}}
function announce(text){$('#status').textContent=text;}
function speak(text){if(state.settings.narration&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.volume=state.settings.volume;u.rate=.85;speechSynthesis.speak(u)}}
let audio;function chime(){if(!state.settings.volume)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=660;g.gain.setValueAtTime(state.settings.volume*.15,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.25);o.start();o.stop(audio.currentTime+.25)}catch{}}
function open(title){if('speechSynthesis'in window)speechSynthesis.cancel();content.replaceChildren();const h=document.createElement('h2');h.textContent=title;content.append(h);if(!panel.open)panel.showModal();}
function button(label,fn,parent=content){const b=document.createElement('button');b.textContent=label;b.onclick=fn;parent.append(b);return b;}
function paragraph(text,cls){const p=document.createElement('p');p.textContent=text;if(cls)p.className=cls;content.append(p);}
function close(){panel.close();if('speechSynthesis'in window)speechSynthesis.cancel()}
$('#close').onclick=close;panel.addEventListener('close',()=>{if('speechSynthesis'in window)speechSynthesis.cancel()});
function card(item){open(item.name);paragraph(item.icon,'illustration');paragraph(item.diagram,'diagram');paragraph(item.text);button('🔊 Listen',()=>{if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance(item.text);u.volume=state.settings.volume;speechSynthesis.cancel();speechSynthesis.speak(u)}});button('↻ Replay',()=>{chime();speak(item.text);const d=content.querySelector('.diagram');d.textContent=item.diagram;d.style.background='#fff0b8'});button('📍 Revisit',()=>{close();select(objects.find(o=>o.id===item.id)||objects.find(o=>o.id==='dig'))});speak(item.text);}
function discover(item){state.discoveries.add(item.id);persist();chime();announce('Discovered: '+item.name);card(item)}
function interact(o){state.last=o.id;if(o.kind==='home'){announce('Back at the starting point. Choose any discovery.');return}if(o.kind==='dig'){state.action='dig';state.timer=state.settings.reduced?.25:1.3;announce('Digging through the soil…');return}discover(o)}
function start(){if(state.started)return;state.started=true;scenes.enter('grounds');$('#begin').hidden=true;announce('Tap a place or a picture to explore. PIP can show you how.');chime();}
function select(o){start();if(state.paused){announce('Tap Resume to keep exploring.');return}state.action=null;state.ring={x:o.x,y:o.y};state.pending=o;state.path=pathfind([state.x,state.y],[o.x-65,o.y+55]);announce('Going to '+o.name);if(!state.path.length)interact(o);}
for(const o of objects){const b=button(o.icon+' ',()=>select(o),$('#targets'));b.className='target';b.dataset.id=o.id;b.style.left=o.x/10+'%';b.style.top=o.y/6+'%';b.setAttribute('aria-label',o.name);const label=document.createElement('small');label.textContent=o.name;b.append(label)}
$('#begin').onclick=start;
canvas.addEventListener('pointerdown',e=>{if(panel.open||state.paused)return;start();const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*1000/r.width,y=(e.clientY-r.top)*600/r.height;if(blocked(...cellAt(x,y))){announce('The pond is water. Tap the path around it.');state.ring={x,y};return}state.path=pathfind([state.x,state.y],[x,y]);state.pending=null;state.action=null;state.ring={x,y};announce('Walking to your marker.');});
$('#pause').onclick=()=>{state.paused=!state.paused;$('#pause').innerHTML=state.paused?'▶ <span>Resume</span>':'Ⅱ <span>Pause</span>';announce(state.paused?'Paused. Take your time.':'Ready to explore.');if(state.paused&&'speechSynthesis'in window)speechSynthesis.cancel()};
$('#journal').onclick=()=>{open('Discovery journal');const found=[...objects,...materials].filter(o=>state.discoveries.has(o.id));if(!found.length)paragraph('⛏️ → 💎  Explore a picture or dig to find your first discovery.');const div=document.createElement('div');div.className='cards';content.append(div);found.forEach(o=>button(o.icon+' '+o.name,()=>card(o),div))};
$('#crew').onclick=()=>{open('Astronaut crew');paragraph('🧑‍🚀 Alex Thompson • Red');paragraph(roster[0][2]);paragraph('Temporary geometric astronaut. Additional canonical characters can be loaded in a future phase.');roster.slice(1).forEach(r=>paragraph(r.join(' • ')))};
$('#pip').onclick=()=>{open('PIP • Your exploration helper');paragraph('🤖 → 👆 → ⛏️','illustration');button('✨ Show places',()=>{close();document.querySelectorAll('.target').forEach(b=>b.classList.add('hint'));announce('The bright pictures are places you can explore.');});button('▶ Show me a dig',()=>{close();select(objects.find(o=>o.id==='dig'))});button('↩ Previous activity',()=>{close();select(objects.find(o=>o.id===state.last)||objects[0])});button('🔊 Repeat guidance',()=>{announce('Tap a picture. Your astronaut walks there and explores. Tap the pickaxe to dig.');speak('Tap a picture. Your astronaut walks there and explores. Tap the pickaxe to dig.')});button('🏠 Return to start',()=>{close();select(objects[0])})};
$('#settings').onclick=()=>{open('Accessibility & sound');const volume=document.createElement('label');volume.textContent='🔊 Volume';const range=document.createElement('input');range.type='range';range.min=0;range.max=1;range.step=.1;range.value=state.settings.volume;range.setAttribute('aria-label','Sound volume');range.oninput=()=>{state.settings.volume=+range.value;persist()};volume.append(range);content.append(volume);for(const [key,label] of [['narration','🔊 Optional narration'],['reduced','🐢 Reduced animation'],['effects','✨ Visual effects']]){const l=document.createElement('label'),i=document.createElement('input');i.type='checkbox';i.checked=state.settings[key];i.onchange=()=>{state.settings[key]=i.checked;persist()};l.append(i,document.createTextNode(label));content.append(l)}paragraph('All activities wait for you. No dragging, fast tapping, scores, or penalties.');};
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(x,y,w,h)}
function draw(t){ctx.clearRect(0,0,1000,600);rect(0,0,1000,600,'#b7d98d');rect(0,0,1000,90,'#a5deeb');ctx.fillStyle='#8ab96e';ctx.beginPath();ctx.ellipse(350,200,200,110,0,0,7);ctx.fill();ctx.strokeStyle='#e8cc94';ctx.lineWidth=70;ctx.lineJoin='round';ctx.beginPath();ctx.moveTo(130,460);ctx.lineTo(290,460);ctx.lineTo(450,420);ctx.lineTo(730,420);ctx.lineTo(830,480);ctx.stroke();ctx.lineWidth=46;ctx.beginPath();ctx.moveTo(290,460);ctx.lineTo(220,245);ctx.lineTo(380,175);ctx.lineTo(500,110);ctx.lineTo(740,110);ctx.lineTo(815,180);ctx.lineTo(710,410);ctx.stroke();rect(520,160,160,160,'#4b9fb6');for(let y=185;y<310;y+=35)rect(540,y,110,5,'#95d5df');rect(735,135,180,100,'#8e6b55');rect(735,125,180,85,'#c6a17c');for(let i=0;i<5;i++)rect(735,220+i*16,150-i*22,13,'#ddbf91');rect(395,440,120,20,'#bd8b60');rect(395,460,120,15,'#986644');rect(395,475,120,12,'#71482f');ctx.fillStyle='#285344';ctx.font='bold 21px system-ui';ctx.fillText('GSEI • DISCOVERY TRAINING GROUNDS',35,46);ctx.font='16px system-ui';ctx.fillText('↖ Hill trail',280,105);ctx.fillText('Auto-climb ramp ↗',745,325);ctx.fillText('← Starting path',55,565);
if(state.ring){ctx.strokeStyle=state.settings.effects?'#fff8b2':'#1a3547';ctx.lineWidth=5;ctx.beginPath();ctx.arc(state.ring.x,state.ring.y,25,0,7);ctx.stroke()}
const x=state.x,y=state.y,bob=state.path.length&&!state.settings.reduced?Math.sin(t/90)*3:0;ctx.fillStyle='#0003';ctx.beginPath();ctx.ellipse(x,y+20,20,7,0,0,7);ctx.fill();rect(x-16,y-15+bob,32,34,'#cf4348');rect(x-12,y+16+bob,9,12,'#23384f');rect(x+4,y+16+bob,9,12,'#23384f');rect(x-19,y-42+bob,38,29,'#f5f4e4');rect(x-13,y-35+bob,26,15,'#28495e');rect(x-25,y-10+bob,8,22,'#e3e5cf');rect(x+17,y-10+bob,8,22,'#e3e5cf');if(state.action==='dig'){ctx.font='30px system-ui';ctx.fillText('⛏️',x+18,y)}if(assets.get('pip'))ctx.drawImage(assets.get('pip'),x+30,y-65,40,40);else{rect(x+36,y-58,26,22,'#f4e9b5');rect(x+41,y-52,16,7,'#39768d');}}
let prev=performance.now();function loop(t){const dt=Math.min((t-prev)/1000,.05);prev=t;if(state.started&&!state.paused&&!panel.open){if(state.path.length){const p=state.path[0],dx=p[0]-state.x,dy=p[1]-state.y,d=Math.hypot(dx,dy),step=150*dt;if(d<=step){[state.x,state.y]=p;state.path.shift();if(!state.path.length&&state.pending){const o=state.pending;state.pending=null;interact(o)}}else{state.x+=dx/d*step;state.y+=dy/d*step}}if(state.action){state.timer-=dt;if(state.timer<=0){state.action=null;discover(materials[state.dug++%materials.length])}}}draw(state.paused?0:t);requestAnimationFrame(loop)}requestAnimationFrame(loop);
